"""Build a self-contained visual report for the overnight stock study."""
from __future__ import annotations

import csv
import json
from pathlib import Path


ROOT = Path(__file__).resolve().parent
OUT = ROOT / "research" / "overnight_equities"


def rows(path: Path) -> list[dict]:
    with path.open(encoding="utf-8") as f:
        return list(csv.DictReader(f))


HTML = r'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Overnight equity research</title><style>
:root{--bg:#08111f;--panel:#101d31;--line:#263853;--text:#e9f1ff;--muted:#9aabc4;--green:#37d69a;--red:#ff7184;--amber:#ffd166;--blue:#76a9ff}*{box-sizing:border-box}body{margin:0;background:linear-gradient(135deg,#07101e,#0b1527 55%,#111b32);color:var(--text);font:14px/1.5 -apple-system,BlinkMacSystemFont,Segoe UI,Arial,sans-serif}main{max-width:1280px;margin:auto;padding:36px 22px 70px}.eyebrow{color:var(--blue);text-transform:uppercase;letter-spacing:.14em;font-size:11px;font-weight:700}h1{font-size:38px;line-height:1.08;margin:8px 0 10px;letter-spacing:-.03em}h2{font-size:18px;margin:0 0 12px}.muted{color:var(--muted)}.warning{border:1px solid #9a6c2f;background:#241d16;border-radius:12px;padding:15px 18px;margin:22px 0}.pill{display:inline-block;background:#5c3516;color:var(--amber);border-radius:999px;padding:3px 9px;font-size:11px;font-weight:700;letter-spacing:.06em}.controls{display:flex;gap:12px;flex-wrap:wrap;align-items:center;margin:20px 0}.controls select{background:#0b172a;color:var(--text);border:1px solid var(--line);padding:9px 11px;border-radius:8px}.cards{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:12px;margin:16px 0}.card,.panel{background:rgba(16,29,49,.88);border:1px solid var(--line);border-radius:12px;padding:16px}.card small{display:block;color:var(--muted);font-size:11px}.card strong{display:block;font-size:25px;margin:4px 0}.grid{display:grid;grid-template-columns:1.45fr .8fr;gap:16px}.chartbox{height:390px}.chartbox canvas{width:100%;height:100%}.tablewrap{overflow:auto;border:1px solid var(--line);border-radius:10px}table{width:100%;border-collapse:collapse;min-width:1000px}th,td{padding:9px 10px;border-bottom:1px solid #21324b;text-align:right;white-space:nowrap}th:first-child,td:first-child{text-align:left}th{color:var(--muted);font-size:11px;text-transform:uppercase;letter-spacing:.05em}td:first-child{font-weight:600}.positive{color:var(--green)}.negative{color:var(--red)}.gate{color:var(--amber);font-weight:700}.sources{display:flex;gap:10px;flex-wrap:wrap}.sources a{color:#9fc2ff}.footer{color:var(--muted);font-size:12px;margin-top:28px}.signal{display:flex;justify-content:space-between;gap:12px;border-bottom:1px solid #21324b;padding:9px 0}.signal:last-child{border-bottom:0}.tag{color:var(--blue);font-weight:700}@media(max-width:800px){.cards{grid-template-columns:repeat(2,minmax(0,1fr))}.grid{grid-template-columns:1fr}h1{font-size:30px}}
</style></head><body><main><div class="eyebrow">Trading Lab · U.S. equities</div><h1>One stock overnight, tested daily</h1><p class="muted">A fixed-universe close-to-next-open screen. One liquid stock is selected after each close and exited at the next regular-session open. Historical paper research only.</p><div class="warning"><span class="pill">NO LIVE ORDERS · POWER AND BENCHMARKS INCLUDED</span><div style="margin-top:8px">SPY buy-and-hold and volatility-matched SPY are the comparison benchmarks. Every model row includes Sharpe error bars and a minimum detectable Sharpe; rows whose confidence interval crosses zero are INCONCLUSIVE.</div></div><div class="controls"><label>Period <select id="period"></select></label><label>Chart model <select id="model"></select></label></div><div class="cards"><div class="card"><small>Selection policy</small><strong id="champion">None</strong><span class="muted">no rank-based champion</span></div><div class="card"><small>SPY holdout</small><strong id="holdout">—</strong><span class="muted">buy-and-hold total return</span></div><div class="card"><small>SPY recent</small><strong id="recent">—</strong><span class="muted">buy-and-hold total return</span></div><div class="card"><small>Model lines</small><strong id="latest">—</strong><span class="muted">all candidates reported</span></div></div><div class="grid"><section class="panel"><h2>Equity curve</h2><div class="chartbox"><canvas id="chart" width="1100" height="380"></canvas></div><div id="note" class="muted"></div></section><section class="panel"><h2>Latest evening ranking</h2><div id="signals"></div><p class="muted" style="margin-top:14px">The last complete session is shown for research. There is no next-session exit yet, so this is not an order instruction.</p></section></div><section class="panel" style="margin-top:16px"><h2>Model comparison</h2><div class="tablewrap"><table><thead><tr><th>Model</th><th>Development</th><th>Validation</th><th>Holdout</th><th>Recent</th><th>Holdout DD</th><th>Sharpe</th><th>95% CI</th><th>Min detectable</th><th>Matched SPY diff</th></tr></thead><tbody id="summary"></tbody></table></div></section><section class="panel" style="margin-top:16px"><h2>Execution stress</h2><div class="tablewrap"><table><thead><tr><th>Period</th><th>Model</th><th>Scenario</th><th>Return</th><th>DD</th><th>Trades</th><th>Bootstrap lower</th></tr></thead><tbody id="stress"></tbody></table></div></section><section class="panel" style="margin-top:16px"><h2>Method and limits</h2><p class="muted">The screen ranks a fixed liquid large-cap universe after the close. SPY buy-and-hold uses split/dividend-adjusted close-to-close total return with no turnover. SPY matched scales that benchmark to each model's realized volatility with 4% cash and borrowing at cash + 50bps. Each model row reports Sharpe, a 95% confidence interval, minimum detectable Sharpe, and the return difference versus matched SPY. The universe has survivorship bias, daily bars do not reconstruct exact closing-auction or opening-quote fills, and the news gate is disabled in this historical run.</p><div class="sources"><a href="SCOREBOARD.md">Scoreboard</a><a href="PHASE1_REPORT.md">Phase 1 report</a><a href="README.md">Study README</a><a href="STRATEGY_RESEARCH.md">Research memo</a><a href="ALPACA_INTEGRATION.md">Alpaca plan</a><a href="paper/index.html">Phase 2 safe paper dashboard</a><a href="paper/fills.csv">Paper fills</a><a href="data_audit.json">Data audit</a><a href="latest_signal.json">Latest signal JSON</a><a href="decision_log.csv">Decision log</a></div></section><div class="footer">$10,000 paper account · split/dividend-adjusted Yahoo research bars · no live orders · not a recommendation</div></main><script>
const DATA=__DATA__;const $=id=>document.getElementById(id);const pct=x=>Number(x).toFixed(2)+'%';const cls=x=>Number(x)>=0?'positive':'negative';const periods=['development','validation','holdout','recent'];const models=['overnight_momentum','overnight_reversal','close_strength','relative_strength','ensemble'];const names=Object.fromEntries(DATA.models.map(x=>[x.id,x.name]));
function row(period,model){return DATA.summary.find(x=>x.period===period&&x.model===model)}
function renderSummary(){const h=row('holdout','spy_buy_hold'),r=row('recent','spy_buy_hold');$('champion').textContent='None';$('holdout').textContent=h?pct(h.return_pct):'—';$('recent').textContent=r?pct(r.return_pct):'—';$('latest').textContent=models.length+' models';$('summary').innerHTML=models.map(m=>{const xh=row('holdout',m)||{},ci=(Number(xh.sharpe_ci_low||0).toFixed(2)+' to '+Number(xh.sharpe_ci_high||0).toFixed(2));return `<tr><td>${names[m]}</td>${periods.map(p=>{const x=row(p,m);return `<td class="${cls(x?.return_pct||0)}">${x?pct(x.return_pct):'—'}</td>`}).join('')}<td>${pct(xh.max_drawdown_pct||0)}</td><td>${Number(xh.sharpe||0).toFixed(2)}</td><td class="${Number(xh.sharpe_ci_low||0)<=0?'gate':'positive'}">${ci}</td><td>${Number(xh.min_detectable_sharpe||0).toFixed(2)}</td><td class="${cls(xh.excess_vs_spy_buy_hold_matched_pct||0)}">${pct(xh.excess_vs_spy_buy_hold_matched_pct||0)}</td></tr>`}).join('')}
function renderSignals(){const latest=DATA.latest_signal;$('signals').innerHTML=latest.models.map(x=>`<div class="signal"><span><b>${x.name}</b><br><span class="muted">score ${x.score==null?'—':Number(x.score).toFixed(3)} · regime ${x.market_regime?'on':'off'}</span></span><span class="tag">${x.symbol}</span></div>`).join('')}
function draw(){const period=$('period').value,model=$('model').value,rows=DATA.daily.filter(x=>x.period===period&&x.model===model),c=$('chart'),ctx=c.getContext('2d'),w=c.width,h=c.height;ctx.clearRect(0,0,w,h);ctx.fillStyle='#101d31';ctx.fillRect(0,0,w,h);if(!rows.length){$('note').textContent='No rows';return}const vals=rows.map(x=>Number(x.equity)),lo=Math.min(...vals),hi=Math.max(...vals),L=62,R=18,T=18,B=32,X=i=>L+i*(w-L-R)/Math.max(1,rows.length-1),Y=v=>T+(hi-v)*(h-T-B)/Math.max(1e-9,hi-lo);ctx.strokeStyle='#263853';ctx.lineWidth=1;for(let j=0;j<5;j++){const yy=T+j*(h-T-B)/4;ctx.beginPath();ctx.moveTo(L,yy);ctx.lineTo(w-R,yy);ctx.stroke();ctx.fillStyle='#9aabc4';ctx.font='11px Arial';ctx.fillText('$'+(hi-(hi-lo)*j/4).toFixed(0),4,yy+4)}ctx.strokeStyle='#76a9ff';ctx.lineWidth=2;ctx.beginPath();rows.forEach((r,i)=>{const xx=X(i),yy=Y(Number(r.equity));i?ctx.lineTo(xx,yy):ctx.moveTo(xx,yy)});ctx.stroke();ctx.fillStyle='#9aabc4';ctx.font='11px Arial';ctx.fillText(rows[0].date,L,h-9);ctx.fillText(rows[rows.length-1].date,w-100,h-9);$('note').textContent=`${names[model]||model} · ${rows.length} sessions · final ${pct(Number(vals.at(-1))/10000-1)} · equity range $${lo.toFixed(0)}–$${hi.toFixed(0)}`}
function renderStress(){const wanted=DATA.stress.filter(x=>x.period==='holdout'||x.period==='recent');$('stress').innerHTML=wanted.map(x=>`<tr><td>${x.period}</td><td>${names[x.model]||x.model}</td><td>${x.scenario}</td><td class="${cls(x.return_pct)}">${pct(x.return_pct)}</td><td>${pct(x.max_drawdown_pct)}</td><td>${x.trades}</td><td class="negative">${pct(x.bootstrap_lower_95_pct)}</td></tr>`).join('')}
for(const p of periods)$('period').insertAdjacentHTML('beforeend',`<option value="${p}">${p}</option>`);for(const m of models)$('model').insertAdjacentHTML('beforeend',`<option value="${m}">${names[m]}</option>`);$('period').value='holdout';$('model').value='overnight_reversal';$('period').onchange=draw;$('model').onchange=draw;renderSummary();renderSignals();renderStress();draw();
</script></body></html>'''


def main() -> None:
    report = json.loads((OUT / "results.json").read_text(encoding="utf-8"))
    report["daily"] = rows(OUT / "daily_results.csv")
    report["stress"] = rows(OUT / "stress.csv")
    page = HTML.replace("__DATA__", json.dumps(report, separators=(",", ":")))
    (OUT / "index.html").write_text(page, encoding="utf-8")
    print(OUT / "index.html")


if __name__ == "__main__":
    main()
